def make(dot_mode, seg_mode):
    # dot_mode: 'keep' or 'overwrite' (dots strictly inside a span become 3)
    # seg_mode: 'minmax' or 'consecutive' (fill only between consecutive dot pairs)
    def f(g):
        n=Counter(x for r in g for x in r); d=n.most_common()[-1][0]
        H,W=len(g),len(g[0]); out=[r[:] for r in g]
        def spans(lines):
            res=[]
            for line in lines:
                ps=[i for i,x in enumerate(line) if x==d]
                if len(ps)>=2:
                    if seg_mode=='minmax': res.append((min(ps),max(ps)))
                    else: res += [(ps[k],ps[k+1]) for k in range(len(ps)-1)]
            return res
        for i,row in enumerate(g):
            for a,b in spans([row]):
                for j in range(a,b+1):
                    if out[i][j]!=d or dot_mode=='overwrite': out[i][j]=3 if seg_mode=='minmax' or j not in (a,b) else out[i][j]
        for j in range(W):
            col=[g[i][j] for i in range(H)]
            for a,b in spans([col]):
                for i in range(a,b+1):
                    if out[i][j]!=d or dot_mode=='overwrite': out[i][j]=3
        return out
    return f
